"""Extract pinned matcher literal rows and assertion predicates, never run a matcher.

Shared explicit runners supply the test-host adaptation. Unknown source forms fail;
--check guards the generated bytes and complete original source provenance.
"""
from pathlib import Path
import hashlib,json,re,sys
ROOT=Path(__file__).resolve().parents[1]
SOURCE=ROOT/'upstream/TypeScript/tsc/internal/vfs/vfsmatch/vfsmatch_test.go'
OUTPUT=ROOT/'validation/Configuration.Checks/MatcherChecks.Generated.cs'
PROVENANCE=ROOT/'validation/Configuration.Checks/matcher-test-provenance.json'
STR=r'"(?:\\.|[^"\\])*"'
raw=SOURCE.read_text()
# Preserve string tokens while removing source comments.
text=re.sub(STR+r'|//[^\n]*|/\*.*?\*/',lambda m:m[0] if m[0].startswith('"') else '',raw,flags=re.S)
def end_bal(s,start):
    close={'{':'}','(':')','[':']'}; stack=[];i=start
    while i<len(s):
        if s[i]=='"':
            m=re.match(STR,s[i:]);assert m;i+=len(m[0]);continue
        if s[i] in close:stack.append(close[s[i]])
        elif stack and s[i]==stack[-1]:
            stack.pop()
            if not stack:return i+1
        i+=1
    raise ValueError('Unclosed source group')
def split(s):
    out=[];start=0;i=0
    while i<len(s):
        if s[i]=='"':i+=len(re.match(STR,s[i:])[0]);continue
        if s[i] in '{([':i=end_bal(s,i);continue
        if s[i]==',':out.append(s[start:i].strip());start=i+1
        i+=1
    out.append(s[start:].strip());return [x for x in out if x]
def func(name):
    m=re.search(r'^func '+re.escape(name)+r'\(',text,re.M)
    if not m:raise ValueError(name)
    start=text.index('{',m.end());return text[start+1:end_bal(text,start)-1]
def fields(row):
    result={}
    for x in split(row.strip()[1:-1]):
        key,value=x.split(':',1);result[key.strip()]=value.strip()
    return result
def q(s):
    # Original tests use Go double-quoted literals. Encode source Unicode to its
    # UTF8 byte-string role before emitting C# (not C# UTF16 display literals).
    return json.dumps(json.loads(s).encode('utf-8').decode('latin1'),ensure_ascii=True)
def coll(s):
    if s=='nil':return 'null'
    start=s.index('{'); vals=split(s[start+1:end_bal(s,start)-1]);return '['+', '.join(expr(v) for v in vals)+']'
def expr(s):
    s=s.strip()
    if s.startswith('[]'):return coll(s)
    s=re.sub(STR,lambda m:q(m[0]),s)
    s=s.replace('tspath.CaseSensitive','CaseSensitivity.CaseSensitive').replace('tspath.CaseInsensitive','CaseSensitivity.CaseInsensitive')
    s=s.replace('UsageFiles','Usage.Files').replace('UsageDirectories','Usage.Directories').replace('UsageExclude','Usage.Exclude')
    s=s.replace('UnlimitedDepth','M.UnlimitedDepth').replace('slices.Contains(', 'Contains(')
    s=re.sub(r'len\((\w+)\)',lambda m:'('+m[1]+'?.Count ?? 0)' if m[1] == 'got' else m[1]+'.Length',s)
    s=re.sub(r'contains\((\w+),\s*('+STR+r')\)',r'\1.Contains(\2, StringComparison.Ordinal)',s)
    s=re.sub(r'hasSuffix\((\w+),\s*('+STR+r')\)',r'\1.EndsWith(\2, StringComparison.Ordinal)',s)
    return s

def host(s):
    if re.fullmatch(r'\w+',s):return s+'()'
    m=re.search(r'vfstest.FromMap\(map\[string\](?:string|any)\{',s)
    if not m:raise ValueError('Host '+s)
    start=m.end()-1; mapping=s[start+1:end_bal(s,start)-1];rows=[]
    for entry in split(mapping):
        key,value=entry.split(':',1)
        value=value.strip()
        if value.startswith('vfstest.Symlink('):rows.append('new('+q(key.strip())+', Symlink: '+q(value[16:-1])+')')
        else:
            if value!='""':raise ValueError('Unexpected contents '+value)
            rows.append('new('+q(key.strip())+')')
    sensitivity=s[end_bal(s,start):].lstrip(', ').split(')')[0].strip()
    return 'new ConfigurationFileSystem(['+', '.join(rows)+'], '+expr(sensitivity)+')'

def assertion_body(s):
    start=s.index('{');s=s[start+1:end_bal(s,start)-1]
    # Explicit original locals and foreach predicates are retained.
    s=re.sub(r'expected := (\[\]string\{)', 'string[] expected = '+r'\1',s)
    s=re.sub(r'\[\]string\{[^}]*\}',lambda m:coll(m[0]),s)
    s=re.sub(r'for _, (\w+) := range (\w+) \{',r'foreach (string \1 in \2 ?? []) {',s)
    s=s.replace('suffix := f[len("/dev/"):]','string suffix = f["/dev/".Length..]')
    s=s.replace('if len(got) == 0 {','if ((got?.Count ?? 0) == 0) {')
    output=[];i=0;cursor=0
    for match in list(re.finditer(r'assert\.(Assert|Equal|DeepEqual)\(',s)):
        if match.start()<i:continue
        start=match.end()-1;end=end_bal(s,start);args=split(s[start+1:end-1]);assert args[0]=='t'
        args=args[1:];kind=match[1]
        if kind=='Assert':replacement='Check.True('+expr(args[0])+', context);'
        elif kind=='Equal':replacement='Check.Equal('+expr(args[0])+', '+expr(args[1])+', context);'
        else:replacement='Check.Sequence<string>('+expr(args[0])+', '+expr(args[1])+', context);'
        output.append(s[cursor:match.start()]);output.append(replacement);cursor=end;i=end
    output.append(s[cursor:]);s=''.join(output)
    s=re.sub(r'(string\[\] expected = \[[^]]*\])',r'\1;',s,flags=re.S)
    s=s.replace('string suffix = f["/dev/".Length..]','string suffix = f["/dev/".Length..];')
    s=re.sub(r'\breturn\s*\n', 'return;\n',s)
    if any(x in s for x in ('assert.',' := ','[]string','range ')):raise ValueError('Unknown expectation '+s)
    return '\n'.join('                '+line.strip() for line in s.strip().splitlines() if line.strip())

names=re.findall(r'^func (Test\w+)\(',text,re.M)
if len(names)!=20:raise ValueError('Original function inventory '+str(len(names)))
methods=[];counts={}
# Source host maps, independent from production.
for name in re.findall(r'^func (\w+Host)\(',text,re.M):
    methods.append('    private static ConfigurationFileSystem '+name+'() => '+host(func(name))+';\n')
for name in names:
    body=func(name)
    table=re.search(r'(?:cases|tests) := (?:\[\]readDirTestCase|\[\]struct \{.*?\})\s*\{',body,re.S)
    if not table:continue
    start=table.end()-1;rows=split(body[start+1:end_bal(body,start)-1]);rows=[fields(row) for row in rows]
    is_read='[]readDirTestCase' in table[0]
    lines=['    private static void '+name+'()', '    {']
    for row in rows:
        lines+=['        {','            const string context = '+q(json.dumps(name+': '+json.loads(row['name'])))+';']
        # q accepts a source string, so context is encoded as an ordinary ASCII string here.
        if is_read:
            current=row.get('currentDir','"/"');path=row.get('path','"/dev"');depth=row.get('depth','UnlimitedDepth')
            lines+=['            IFS host = '+host(row['host'])+';',
                '            RootedDirectoryPath path = TsPath.ToRootedDirectoryPath('+expr(path)+', TsPath.RootedDirectoryPathFromAbsolute('+expr(current)+'));',
                '            List<string>? got = GoSlices.ToListOrNull(M.ReadDirectory(host, path, '+coll(row.get('extensions','nil'))+', (List<string>?)'+coll(row.get('excludes','nil'))+', '+coll(row.get('includes','nil'))+', '+expr(depth)+'))?.Select(value => value.AsString()).ToList();',
                assertion_body(row['expect'])]
        elif 'input' in row:
            lines+=['            Check.Equal(M.IsImplicitGlob('+expr(row['input'])+'), '+expr(row['expected'])+', context);']
        else:
            specs=coll(row['specs']) if 'specs' in row else '['+expr(row['spec'])+']'
            lines+=['            var matcher = M.NewSpecMatcher((List<string>?)'+specs+', RootedDirectoryPath.FromGoString('+expr(row['basePath'])+'), '+expr(row['usage'])+', '+expr(row['caseSensitivity'])+');']
            if row.get('expectNil')=='true':lines+=['            Check.True(matcher is null, context + " should be nil");']
            else:
                lines+=['            Check.True(matcher is not null, context + " should not be nil");']
                for key,result in [('matchingPaths','true'),('nonMatchingPaths','false')]:
                    if key in row:
                        lines+=['            foreach (string path in (string[])'+coll(row[key])+') Check.Equal(matcher!.MatchString(path), '+result+', context + path);']
                if 'paths' in row:
                    lines+=['            string[] paths = '+coll(row['paths'])+';', ('            int[]' if name=='TestSpecMatchers_MatchIndex' else '            bool[]')+' expected = '+coll(row['expected'])+';', '            Check.Equal(paths.Length, expected.Length, context);',
                        '            for (int i = 0; i < paths.Length; i++) Check.Equal(matcher!.'+('MatchIndex' if name=='TestSpecMatchers_MatchIndex' else 'MatchString')+'(paths[i]), expected[i], context + paths[i]);']
                if 'pathToIndex' in row:
                    mapping=row['pathToIndex'];pos=mapping.index('{')
                    for entry in split(mapping[pos+1:end_bal(mapping,pos)-1]):
                        key,value=entry.split(':',1);lines+=['            Check.Equal(matcher!.MatchIndex('+q(key.strip())+'), '+expr(value)+', context);']
        lines+=['        }']
    lines+=['    }\n'];methods.append('\n'.join(lines));counts[name]={'rows':len(rows),'predicateSourcePreserved':True}

output='''// Copyright (c) Microsoft Corporation. All rights reserved.
// Licensed under the Apache License, Version 2.0. See licenses/TypeScript-LICENSE.txt.
// Generated literal inputs AND original expectation predicates; no execution oracle.
// tools/configuration-generate-matcher-tests.py guards source/table bytes.
#nullable enable
using TypeScript.Scanner;
using TypeScript.Vfs;
using TypeScript.Vfs.VfsMatch;
using M = TypeScript.Vfs.VfsMatch.VfsMatch;
namespace Configuration.Checks;
public static partial class MatcherChecks
{
'''+ '\n'.join(methods)+'}\n'
provenance=json.dumps({'pin':'fed0bf24149fb1ed36039212648bafdafc1ea10e','source':str(SOURCE.relative_to(ROOT)),'sourceSha256':hashlib.sha256(SOURCE.read_bytes()).hexdigest(),'originalFunctions':names,'generatedTables':counts,'manualBodies':[n for n in names if n not in counts],'policy':'All rows and original predicates; read-only host adaptation, no inferred expected output.'},indent=2)+'\n'
for path,data in [(OUTPUT,output),(PROVENANCE,provenance)]:
    if '--check' in sys.argv:
        if not path.exists() or path.read_text()!=data:raise SystemExit('Generated drift: '+str(path))
    else:path.write_text(data)
print('Matcher tables:',sum(row['rows'] for row in counts.values()),'rows in',len(counts),'original functions; remaining explicit bodies:',20-len(counts))
